from __future__ import absolute_import
from taf.selenium.sbts_fsm3.pages import v23r1
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.pages.modals import ScheduleForcedBTSResetModal


class Procedures(v23r1.Procedures):
    def __init__(self, driver):
        super(Procedures, self).__init__(driver)
        self._bts_power_reset = BtsPowerRestPage(driver)
        self._schedule_forced_bts_reset = ScheduleForcedBTSResetPage(driver)

    @property
    def schedule_forced_bts_reset(self):
        return self._schedule_forced_bts_reset


class BtsPowerRestPage(v23r1.procedures.BtsPowerRestPage):

    def __init__(self, driver):
        super(BtsPowerRestPage, self).__init__(driver)
        self._view_panel = BtsPowerRestPageViewPanel(driver)

    def power_reset(self, timeout=60, with_snapshot_collection=False):
        return self._view_panel.power_reset(timeout, with_snapshot_collection)

    def cancel_snapshot_with_power_reset(self, timeout=60):
        return self._view_panel.cancel_snapshot_with_power_reset(timeout)


class BtsPowerRestPageViewPanel(v23r1.procedures.BtsPowerRestPageViewPanel):
    POWER_RESET_WITH_SNAPSHOT_COLLECTION = '//*[text()="Power reset with snapshot collection"]'
    CANCEL_RESET_WITH_SNAPSHOT_COLLECTION = '//*[text()="Cancel Snapshot"]'
    CANCEL_RESET_STATUS = '//span[contains(text(), "Cancelling snapshot succeed")]'

    def __init__(self, driver):
        super(BtsPowerRestPageViewPanel, self).__init__(driver)

    def power_reset(self, timeout=60, with_snapshot_collection=False):
        if with_snapshot_collection:
            self.click_enabled_element((By.XPATH, self.POWER_RESET_WITH_SNAPSHOT_COLLECTION), timeout)
        else:
            self.click_enabled_element((By.XPATH, self.POWER_RESET), timeout)
        return super(BtsPowerRestPageViewPanel, self).power_reset(timeout)

    def cancel_snapshot_with_power_reset(self, timeout=60):
        self.click_enabled_element((By.XPATH, self.CANCEL_RESET_WITH_SNAPSHOT_COLLECTION), timeout)
        try:
            self.wait_for_visibility_by_xpath(self.CANCEL_RESET_STATUS, timeout)
        except TimeoutException:
            pass
        finally:
            return self.get_text_by_xpath(self.RESET_STATUS, timeout)


class ScheduleForcedBTSResetPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Procedures', 'Schedule Forced BTS Site Reset']

    def __init__(self, driver):
        super(ScheduleForcedBTSResetPage, self).__init__(driver)
        self._view_panel = ScheduleForcedBTSResetPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def schedule_forced_bts_reset(self, timeout=60):
        return self._view_panel.schedule_forced_bts_reset(timeout)


class ScheduleForcedBTSResetPageViewPanel(ViewPanel):
    _EXECUTE_BUTTON = '//*[@class="schedule-forced-bts-site-reset-root"]//button'
    _SCHEDULE_RESET_STATUS = '//*[@class="schedule-forced-bts-site-reset-root"]//span[contains(@class, "ot-text")]'

    def __init__(self, driver):
        super(ScheduleForcedBTSResetPageViewPanel, self).__init__(driver)

    def schedule_forced_bts_reset(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._EXECUTE_BUTTON), timeout)
        emergency_reset_modal = ScheduleForcedBTSResetModal(self.driver)
        emergency_reset_modal.wait_until_emergency_reset_modal_appear(timeout)
        emergency_reset_modal.execute(timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._SCHEDULE_RESET_STATUS), 'succeeded')
        return self.get_text_by_xpath(self._SCHEDULE_RESET_STATUS)
